function TreeNode(val, left, right) {
  this.val = (val===undefined ? 0 : val);
  this.left = (left===undefined ? null : left);
  this.right = (right===undefined ? null : right);
}

// 按层分组的层序遍历
function levelOrder(root) {
  const ans = [];
  if (!root) return ans;
  const q = [root];
  while (q.length) {
    const levelSize = q.length;   // 关键：固定本层节点数
    const level = [];
    for (let i = 0; i < levelSize; i++) {
      const node = q.shift();      // 生产代码建议用真正的队列结构
      level.push(node.val);
      if (node.left) q.push(node.left);
      if (node.right) q.push(node.right);
    }
    ans.push(level);
  }
  return ans;
}

// 之字形：加层号，偶数层反转
function zigzagLevelOrder(root) {
  const ans = [];
  if (!root) return ans;
  const q = [root];
  let leftToRight = true;
  while (q.length) {
    const levelSize = q.length, level = [];
    for (let i = 0; i < levelSize; i++) {
      const node = q.shift();
      if (leftToRight) level.push(node.val);
      else level.unshift(node.val);          // 反向层头插
      if (node.left) q.push(node.left);
      if (node.right) q.push(node.right);
    }
    ans.push(level);
    leftToRight = !leftToRight;
  }
  return ans;
}

// 小顶堆：用数组存储，0 基下标
class MinHeap {
  constructor() { this.a = []; }
  size() { return this.a.length; }
  top() { return this.a[0]; }
  push(x) {
    this.a.push(x);
    let i = this.a.length - 1;
    while (i > 0) { // 上浮
      const p = (i - 1) >> 1;
      if (this.a[p] <= this.a[i]) break;
      [this.a[p], this.a[i]] = [this.a[i], this.a[p]];
      i = p;
    }
  }
  pop() {
    const top = this.a[0], last = this.a.pop();
    if (this.a.length) {
      this.a[0] = last;
      let i = 0, n = this.a.length;
      while (true) { // 下沉
        let l = 2 * i + 1, r = l + 1, smallest = i;
        if (l < n && this.a[l] < this.a[smallest]) smallest = l;
        if (r < n && this.a[r] < this.a[smallest]) smallest = r;
        if (smallest === i) break;
        [this.a[smallest], this.a[i]] = [this.a[i], this.a[smallest]];
        i = smallest;
      }
    }
    return top;
  }
}

function topK(nums, k) {
  if (k <= 0) return [];
  const heap = new MinHeap();
  for (const x of nums) {
    if (heap.size() < k) heap.push(x);
    else if (x > heap.top()) { heap.pop(); heap.push(x); }
  }
  return heap.a; // 堆内即最大的 k 个，顺序不保证
}

class TrieNode {
  constructor() { this.children = new Array(26).fill(null); this.end = false; }
}
class Trie {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      const idx = ch.charCodeAt(0) - 97;
      if (!node.children[idx]) node.children[idx] = new TrieNode();
      node = node.children[idx];
    }
    node.end = true;                       // 标记单词结尾
  }
  _walk(prefix) {                          // 公共下钻逻辑
    let node = this.root;
    for (const ch of prefix) {
      const idx = ch.charCodeAt(0) - 97;
      if (!node.children[idx]) return null;
      node = node.children[idx];
    }
    return node;
  }
  search(word) {
    const node = this._walk(word);
    return node !== null && node.end;      // 必须是完整单词
  }
  startsWith(prefix) {
    return this._walk(prefix) !== null;    // 前缀走通即可
  }
}
